/**
 * TrackDef: the def FACTORY. A raw circuit def (src/circuits/defs/<id>.ts)
 * becomes a built LIST entry here: the palette (dayPal / nightPal), the SRTM
 * elevation readers, the real-centreline point builder (realPoints /
 * applyHwZones) and the field-by-field copy. Ported verbatim from f1-game
 * js/track/core/def.js (TrackDef, :1-311).
 *
 * Differences from f1-game, none of which change a number:
 * - `CircuitElevations` is the baked table ./elevations.ts (the f1-game global is
 *   generated by tools/gen/bake-elevation.mjs; tools/codemod-elevations.mjs copies it).
 * - `TrackSceneryData.GP_DISTANCE_KM` (js/track/scenery/data.js:206) is inlined.
 * - `scenery` (the circuit's dressing closure) is not copied: the scenery lane
 *   owns it (TODO(lane-scenery)).
 */
import type {
  BankZone, BarrierColours, Bridge, CircuitDef, CircuitPath, CityStyle, DressingExclusion,
  Elevation, Furniture, HwZone, Kit, Palette, PitSpec, SceneryThemeOverrides, StandLivery, TerrainMat,
} from "../../circuits/types";
import { CIRCUIT_ELEVATIONS } from "./elevations";
import { norm } from "./geom";
import { racingNodeToSource, range, toRacingFrac, wrap01 } from "./space";
import type { RV3, V3 } from "./types";

const __M = Math;

/** js/track/scenery/data.js:206 */
const GP_DISTANCE_KM: Readonly<Record<string, number>> = { default: 305, monaco: 260 };

/** A centreline control point: [x, y, z, halfWidth, bank]. */
export type ControlPoint = [number, number, number, number, number];

/** The resolved palette (every key present, sunDir normalised). def.js:15 */
export interface ResolvedPalette {
  zenith: RV3; horizon: RV3; sun: RV3;
  grass: RV3; runoff: RV3; fog: RV3;
  asphalt: RV3; line: RV3;
  fogDensity: number; kerbA: RV3; kerbB: RV3;
  ambientSky: RV3; ambientGround: RV3;
  sunColor: RV3; sunDir: V3;
  fogColor?: RV3;
}

/** An authored racing-line hint (line.js resolveHints); designer-only, no shipped def has one. */
export interface LineHint {
  turn: number;
  apexShift?: number;
  apexInside?: number;
}

/**
 * Extra keys a raw def may carry beyond the shipped CircuitDef schema: the
 * track designer's optional surface keys (def.js:145-150) and the opt-in spline.
 */
export interface RawDefExtras {
  kerbStyle?: "sausage" | "rumble" | "flat";
  berms?: boolean;
  splineAlpha?: number;
  lineHints?: readonly LineHint[];
  custom?: boolean;
  _metaOnly?: boolean;
}

export type RawDef = CircuitDef & RawDefExtras;

/** A built LIST entry: def.js:132 fromRaw's output, plus the fields the build stamps on it. */
export interface BuiltDef {
  id: string; name: string; gp: string; country: string; laps: number;
  gpLaps: number;
  night: boolean; theme: string; lengthKm: number;
  classic: boolean; custom: boolean;
  palette: ResolvedPalette;
  street: boolean; banked: boolean; bankZones: readonly BankZone[] | null; bridges: readonly Bridge[] | null;
  kerbStyle?: "sausage" | "rumble" | "flat";
  berms?: boolean;
  barrierGap: number | null;
  terrainOuter: number | undefined;
  terrainFalloffStart?: number;
  flatTerrain: boolean;
  terrainMat?: TerrainMat;
  sceneryCoordinates: string;
  sceneryLapMirror: boolean;
  dressingExclusions: readonly DressingExclusion[] | null;
  tyreSeverity: number | undefined;
  sunAzimBias: number | undefined;
  sceneryTheme: string | undefined;
  sceneryThemeOverrides: SceneryThemeOverrides | null;
  ownPitStraight: boolean;
  pit: PitSpec | null;
  undulate: boolean | undefined;
  elevations: readonly Elevation[] | null;
  hwZones: readonly HwZone[] | null;
  splineAlpha?: number;
  reverse: boolean;
  startFrac: number;
  sceneryStartFrac: number | null;
  sectors: readonly number[] | null; turns: readonly number[] | null; path: CircuitPath | null;
  lineHints: readonly LineHint[] | null;
  barrier: BarrierColours | null; furniture: Furniture | null; kit: Kit | null;
  standSet: readonly StandLivery[] | null; cityStyle: CityStyle | null;
  /** Lazily materialised control points (def.js:242 getter). */
  points: ControlPoint[];
  _metaOnly?: boolean;
  /** Set by materializeListPoints when the lap is rotated or reversed. */
  _startFrac?: number;
  /** Set by buildCenterline (tracks.js:71); see space.ts sceneryOriginDelta. */
  _sceneryShift?: number;
}

const DAY_PAL = (): ResolvedPalette => ({
  zenith: [0.18, 0.40, 0.78], horizon: [0.62, 0.74, 0.88], sun: [1, 0.96, 0.85],
  grass: [0.18, 0.42, 0.16], runoff: [0.55, 0.42, 0.28], fog: [0.62, 0.74, 0.88],
  asphalt: [0.16, 0.17, 0.19], line: [0.95, 0.95, 0.98],
  fogDensity: 0.0017, kerbA: [0.85, 0.12, 0.12], kerbB: [0.95, 0.95, 0.95],
  ambientSky: [0.45, 0.52, 0.62], ambientGround: [0.22, 0.22, 0.18],
  sunColor: [1, 0.95, 0.82], sunDir: [0.4, 0.72, 0.3],
});
const NIGHT_PAL = (): ResolvedPalette => ({
  zenith: [0.05, 0.06, 0.14], horizon: [0.12, 0.14, 0.24], sun: [0.4, 0.4, 0.5],
  grass: [0.14, 0.18, 0.14], runoff: [0.28, 0.26, 0.24], fog: [0.08, 0.09, 0.15],
  asphalt: [0.18, 0.19, 0.22], line: [0.9, 0.9, 0.95],
  fogDensity: 0.0023, kerbA: [0.85, 0.12, 0.12], kerbB: [0.92, 0.92, 0.92],
  ambientSky: [0.62, 0.64, 0.76], ambientGround: [0.44, 0.44, 0.48],
  sunColor: [0.7, 0.72, 0.8], sunDir: [0.1, 0.9, 0.2],
});

function resolvePal(base: () => ResolvedPalette, o: Palette | null | undefined): ResolvedPalette {
  // Object.assign over a fresh defaults literal, as def.js does.
  const p = Object.assign(base(), o) as ResolvedPalette;
  // Tracks historically authored fogColor; runtime reads fog.
  if (o && o.fogColor && o.fog == null) p.fog = o.fogColor;
  p.sunDir = norm(p.sunDir);
  return p;
}

/** def.js:15 */
export function dayPal(o?: Palette | null): ResolvedPalette { return resolvePal(DAY_PAL, o); }
/** def.js:30 */
export function nightPal(o?: Palette | null): ResolvedPalette { return resolvePal(NIGHT_PAL, o); }

/**
 * Surveyed elevation at a lap fraction: Catmull-Rom through the 64-sample
 * profile, or null when the circuit has none. def.js:52
 */
export function elevationAt(id: string, frac: number): number | null {
  const prof = CIRCUIT_ELEVATIONS[id];
  if (!prof || !prof.length) return null;
  const M = prof.length, f = (((frac % 1) + 1) % 1) * M;
  const i = Math.floor(f) % M, t = f - Math.floor(f);
  if (M < 4) return prof[i]! + (prof[(i + 1) % M]! - prof[i]!) * t;
  const p0 = prof[(i - 1 + M) % M]!, p1 = prof[i]!;
  const p2 = prof[(i + 1) % M]!, p3 = prof[(i + 2) % M]!;
  const t2 = t * t, t3 = t2 * t;
  return 0.5 * ((2 * p1) + (-p0 + p2) * t +
                (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 +
                (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
}

/** def.js:66 */
export function hasRealElevation(id: string): boolean {
  return !!(CIRCUIT_ELEVATIONS[id] && CIRCUIT_ELEVATIONS[id].length);
}

/** def.path (the OSM trace) is the ONLY centreline: no path is a build error. def.js:71 */
export function realPoints(id: string, path: CircuitPath | null | undefined, baseHW: number): ControlPoint[] {
  if (!path || !path.pts || !path.pts.length) throw new Error("Tracks: circuit \"" + id +
    "\" has no `path` — src/circuits/defs/" + id + ".ts must carry `path: { len, pts }`");
  const real = hasRealElevation(id);
  const src = path.pts as readonly (readonly number[])[];
  const N = src.length;
  const arc = new Float64Array(N + 1);
  // path.pts are [x, z] (shipped + custom plan) or [x, z, y] for designer heights.
  for (let i = 1; i <= N; i++) { const a = src[i - 1]!, b = src[i % N]!; arc[i] = arc[i - 1]! + __M.hypot(b[0]! - a[0]!, b[1]! - a[1]!); }
  const pts: ControlPoint[] = src.map((p, i): ControlPoint => {
    const authored = !real && p.length >= 3 && Number.isFinite(+p[2]!) ? +p[2]! : 0;
    return [p[0]!, real ? elevationAt(id, arc[i]! / arc[N]!)! : authored, p[1]!, baseHW, 0];
  });
  for (let it = 0; it < 2; it++) {
    const sx = pts.map((p) => p[0]), sz = pts.map((p) => p[2]);
    const L = 0.25;
    for (let i = 0; i < N; i++) {
      const a = (i - 1 + N) % N, b = (i + 1) % N;
      pts[i]![0] = sx[i]! + L * ((sx[a]! + sx[b]!) * 0.5 - sx[i]!);
      pts[i]![2] = sz[i]! + L * ((sz[a]! + sz[b]!) * 0.5 - sz[i]!);
    }
  }
  if (real) {
    const eEnd = pts[N - 1]![1] - pts[0]![1];
    for (let i = 0; i < N; i++) pts[i]![1] -= eEnd * (arc[i]! / arc[N - 1]!);
  }
  return pts;
}

/** def.js:113 */
export function applyHwZones(pts: ControlPoint[], zones: readonly HwZone[] | null | undefined, baseHW: number): void {
  if (!zones || !zones.length || !pts || !pts.length) return;
  const N = pts.length;
  const smooth = (t: number) => { t = Math.max(0, Math.min(1, t)); return t * t * (3 - 2 * t); };
  const weightAt = (s: number, s0: number, s1: number, ease: number) => {
    const wrap = s1 < s0;
    const inside = wrap ? (s >= s0 || s <= s1) : (s >= s0 && s <= s1);
    if (inside) return 1;
    const dEdge = (a: number, b: number) => Math.min(Math.abs(a - b), 1 - Math.abs(a - b));
    const d0 = dEdge(s, s0), d1 = dEdge(s, s1);
    const d = Math.min(d0, d1);
    if (d >= ease) return 0;
    return smooth(1 - d / ease);
  };
  for (let i = 0; i < N; i++) {
    const s = i / N;
    const hw = pts[i]![3];
    let best = hw;
    for (let z = 0; z < zones.length; z++) {
      const zn = zones[z]!;
      if (zn.hw == null || zn.s0 == null || zn.s1 == null) continue;
      const ease = zn.ease != null ? zn.ease : 0.025;
      const w = weightAt(s, zn.s0, zn.s1, ease);
      if (w <= 0) continue;
      const blended = baseHW + (zn.hw - baseHW) * w;
      if (blended < best) best = blended;
    }
    pts[i]![3] = best;
  }
}

/** The LIST entry: a known shape copied field by field off the authored def. def.js:132 */
export function fromRaw(d: RawDef): BuiltDef {
  const def = {
    id: d.id, name: d.name, gp: d.gp, country: d.country, laps: 3,
    gpLaps: Number.isInteger(d.gpLaps) && d.gpLaps! > 3 ? d.gpLaps!
      : Math.ceil((GP_DISTANCE_KM[d.id] || GP_DISTANCE_KM.default!) / (d.lengthKm || 5)),
    night: d.night, theme: d.theme, lengthKm: d.lengthKm,
    classic: !!d.classic, custom: !!d.custom,
    palette: (d.night ? nightPal : dayPal)(d.pal || {}),
    street: !!d.street, banked: !!d.banked, bankZones: d.bankZones || null, bridges: d.bridges || null,
    ...(d.kerbStyle === "sausage" || d.kerbStyle === "rumble" || d.kerbStyle === "flat" ? { kerbStyle: d.kerbStyle } : {}),
    ...(d.berms === true || d.berms === false ? { berms: !!d.berms } : {}),
    barrierGap: d.barrierGap || null,
    terrainOuter: d.terrainOuter,
    ...(Number.isFinite(d.terrainFalloffStart) && d.terrainFalloffStart! >= 30 &&
        d.terrainFalloffStart! < Math.max(0.5, Number(d.terrainOuter) || (d.street ? 28 : 120))
      ? { terrainFalloffStart: d.terrainFalloffStart! } : {}),
    flatTerrain: !!d.flatTerrain,
    ...(d.terrainMat === "SAND" || d.terrainMat === "SNOW" || d.terrainMat === "CONCRETE" ? { terrainMat: d.terrainMat } : {}),
    sceneryCoordinates: d.sceneryCoordinates || "legacy",
    sceneryLapMirror: !!d.sceneryLapMirror,
    dressingExclusions: d.dressingExclusions || null,
    tyreSeverity: d.tyreSeverity,
    sunAzimBias: d.sunAzimBias,
    sceneryTheme: d.sceneryTheme,
    sceneryThemeOverrides: d.sceneryThemeOverrides || null,
    ownPitStraight: !!d.ownPitStraight,
    pit: d.pit || null,
    undulate: d.undulate,
    elevations: hasRealElevation(d.id) ? null : (d.elevations || null),
    hwZones: d.hwZones || null,
    ...(d.splineAlpha != null ? { splineAlpha: d.splineAlpha } : {}),
    reverse: !!d.reverse,
    startFrac: d.startFrac || 0,
    sceneryStartFrac: d.sceneryStartFrac != null ? d.sceneryStartFrac : null,
    sectors: d.sectors || null, turns: d.turns || null, path: d.path || null,
    lineHints: d.lineHints || null,
    barrier: d.barrier || null, furniture: d.furniture || null, kit: d.kit || null,
    standSet: d.standSet || null, cityStyle: d.cityStyle || null,
  } as Omit<BuiltDef, "points"> as BuiltDef;
  // Lazy points: the getter replaces itself with a data property after
  // materialising (def.js:242) — bit-identical once touched.
  Object.defineProperty(def, "points", {
    configurable: true,
    enumerable: true,
    get() { return materializeListPoints(def, d); },
  });
  return def;
}

/** def.js:250 */
export function materializeListPoints(def: BuiltDef, d: RawDef): ControlPoint[] {
  let pts = realPoints(d.id, def.path, d.baseHW);
  const phi = wrap01(def.startFrac || 0);
  const phiAuthor = def.sceneryStartFrac != null ? wrap01(def.sceneryStartFrac) : phi;
  if (def.reverse || phi || phiAuthor) {
    if (def.reverse || phi) {
      const P = pts, N = P.length, out: ControlPoint[] = new Array<ControlPoint>(N);
      for (let i = 0; i < N; i++) out[i] = P[racingNodeToSource(def, i, N)]!;
      pts = out;
    }
    def._startFrac = phi;
    // Elevation and bridge anchors are dressing, remapped against the
    // AUTHORING origin (def.js:262-293 explains why both steps are required).
    const fmap = (s: number) => toRacingFrac({ startFrac: phiAuthor, reverse: def.reverse }, s);
    if (def.elevations) def.elevations = def.elevations.map((e) => Object.assign({}, e, { s: fmap(e.s) }));
    if (def.bridges) def.bridges = def.bridges.map((b) => Object.assign({}, b, { s: fmap(b.s) }));
    if (def.hwZones && (def.reverse || phi)) {
      def.hwZones = def.hwZones.map((z) => Object.assign({}, z, range(def, z.s0, z.s1, "source")));
    }
  }
  // Apply after startFrac remap so authored s0/s1 stay in racing-lap space.
  if (def.hwZones) applyHwZones(pts, def.hwZones, d.baseHW);
  Object.defineProperty(def, "points", {
    value: pts, writable: true, configurable: true, enumerable: true,
  });
  return pts;
}
